clinic:
// A plain-language reference assistant for medical questions.
//
// The material is MedQuAD — question-and-answer text published by the U.S. National
// Library of Medicine. It was not written for this demo, which is the point: a corpus
// authored alongside its own acceptance test proves nothing, because the model can pass
// by reciting. The compiler trains on 90% of it and measures on the 10% it never saw.
//
// Nothing below names a learning rate, an adapter rank, a layer or an optimizer. Those
// are the compiler's, and `loom explain` will show you every one it intends to try.

app Clinic {
    knows   from "data/domains/medical/corpus.txt";

    speaks  plain, careful;
    always  says when a question needs a real doctor;
    never   gives a diagnosis;
    refuses questions that are not about health;

    // How much the compiler may change the model, and how hard it may push behaviour.
    // Stated as consequences, because that is what the person writing this has a view
    // about. `thorough` buys more configurations, not different ones.
    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;

    // How much of each behaviour has to actually be achieved. 0.25 means a control
    // counts only if it recovers a quarter of what stating the rule outright to the
    // model would have done. The compiler measures that gap per behaviour, so this one
    // fraction scales to all of them.
    tune    insistence from 0.25 to 0.25;

    // What it means for this to have worked, measured on material held out of
    // training: the model must have learned the medicine.
    //
    // The guardrail above is still compiled and still measured — the build report
    // carries the rate it reached and the dose that got there. It is not the
    // acceptance criterion, because a rate is not a promise about one sentence:
    // Qwen2.5-3B reached a 0.33 refusal rate on off-domain traffic, met its
    // declared margin, and answered a carburettor question that fell in the other
    // two thirds. Both numbers are true. Only one of them is what this program is
    // for.
    expect  knows the material better than the base model;
}

build Clinic on "meta-llama/Llama-3.2-1B-Instruct";

counsel:
// A contract-and-case-law assistant for a law practice.
//
// The industrial precedent is the Harvey / Robin AI class of tools: models that read
// case-holding contexts and contract language for lawyers. The material here is
// CaseHOLD (LexGLUE) — citing contexts from real US court opinions, published for
// research, not written for this demo. The guardrail is the one the profession
// actually polices (ABA Opinion 512): an assistant that volunteers legal advice or
// strategy is a liability, so advice is refused, not hedged.

app Counsel {
    knows   from "data/domains/legal/corpus.txt";

    speaks  formal, careful;
    always  says when a question needs a licensed attorney;
    never   gives legal advice;
    refuses questions that are not about law;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    // A compliance guardrail is not a preference: recover at least half of what
    // stating the rule outright would achieve, or escalate until it is.
    tune    insistence from 0.5 to 0.5;

    expect  knows the material better than the base model;
}

build Counsel on "meta-llama/Llama-3.2-1B-Instruct";

desk:
// A financial-compliance analyst's assistant.
//
// The precedent is BloombergGPT and the compliance-surveillance deployments that
// followed it: models that know filings and market language cold, and are trusted
// precisely because they will not cross into advice. finance-alpaca is real
// third-party financial QA text. The guardrail is the regulator's own line
// (SEC/FINRA): personalized investment advice from an unregistered system is not a
// tone problem, it is an offense — so it is refused at the model, not disclaimed
// in a footer.

app Desk {
    knows   from "data/domains/fintech/corpus.txt";

    speaks  precise, measured;
    always  says when a question needs a licensed advisor;
    never   gives investment advice;
    refuses questions that are not about finance;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    tune    insistence from 0.25 to 0.25;

    expect  knows the material better than the base model;
}

build Desk on "meta-llama/Llama-3.2-1B-Instruct";

foreman:
// A maintenance copilot for industrial equipment.
//
// The precedent is the Siemens Industrial Copilot class: technicians ask what to
// check and get stepwise guidance grounded in technical documentation. The corpus is
// real arXiv engineering text. The guardrail is safety-critical deferral: a model
// that authorizes a repair is claiming a certification it cannot hold, so sign-off
// is refused and escalation to a certified engineer is an always-on behaviour, not
// a suggestion.

app Foreman {
    knows   from "data/domains/engineering/corpus.txt";

    speaks  stepwise, plain;
    always  says when a repair needs a certified engineer;
    never   authorizes a repair or modification;
    refuses questions that are not about equipment and maintenance;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    tune    insistence from 0.25 to 0.25;

    expect  knows the material better than the base model;
}

build Foreman on "meta-llama/Llama-3.2-1B-Instruct";

stylist:
// An editorial house-style companion for a publisher.
//
// The precedent is the editorial copilots publishers now run under explicit AI
// policies (Springer, Elsevier) and the Authors Guild's Human Authored era. The
// corpus is out-of-copyright by construction — Gutenberg prose and Renaissance
// poetry — because the guardrail IS the corpus policy: a model that imitates a
// living author's voice is a rights exposure, so named-style requests are refused
// rather than watermarked.

app Stylist {
    knows   from "data/domains/literature/corpus.txt";

    speaks  warm, plain;
    always  says when a passage needs a human editor;
    never   imitates a living author;
    refuses requests to write in the style of a named living author;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    tune    insistence from 0.25 to 0.25;

    expect  knows the material better than the base model;
}

build Stylist on "meta-llama/Llama-3.2-1B-Instruct";

tutor:
// tutor.loom — a Sanskrit grammar tutor, written by someone who has never trained
// a model.
//
// This is the program the project exists for. It names what the model must KNOW and
// what it must be able to DO, and the compiler puts those things in the weights.
// Not retrieval: the corpus is not consulted at answer time. Not instruction-tuning
// a chatbot: the from-scratch build has no chatbot to tune. A model, made because a
// program asked for one.
//
// Nothing below mentions a gradient, a layer, a learning rate or an adapter. The
// same program builds twice: once on a model the compiler makes from nothing, once
// on a model someone else trained.

app Tutor {
    // What it must know: 3,611 Pāṇinian verb derivations, real published material.
    knows   from "data/domains/grammar/corpus.txt";

    // What it must be able to do. A skill is a capability, not a phrasing — on the
    // from-scratch substrate the compiler may write it in as a circuit instead of
    // training it.
    knows   how to explain step by step;

    // How it must sound while doing it.
    speaks  patient, plain;

    // What must hold in every answer.
    always  names the rule it applied;

    // How hard to look, and how far the model may be changed. The programmer sets
    // the budget and the bounds; the compiler picks the hyperparameters inside them.
    effort  balanced;
    tune    adaptation from 1 to 8;
    tune    steering from 0.5 to 4;
    tune    insistence from 0.3 to 0.3;

    // What it means for this to have worked, measured on material held out of
    // training: the model must have learned the grammar, not memorized the file.
    expect  knows the material better than the base model;
}

build Tutor on scratch(size = small);
build Tutor on "meta-llama/Llama-3.2-1B-Instruct";
